export function BrandLogo({
  name,
  category,
  className = "h-7 w-7",
}: {
  name: string;
  category?: string;
  className?: string;
}) {
  const svg = BRAND_SVGS[name];

  if (svg) {
    return (
      <svg
        viewBox={svg.viewBox}
        className={className}
        dangerouslySetInnerHTML={{ __html: svg.body }}
        aria-hidden
      />
    );
  }

  // Category-based fallback icon with authentic color accent
  if (category?.includes("Security") || category?.includes("Posture") || category?.includes("Compliance")) {
    return <FiShield className={`${className} text-rose-500`} aria-hidden />;
  }
  if (category?.includes("Data") || category?.includes("Storage") || category?.includes("Database")) {
    return <FiDatabase className={`${className} text-cyan-500`} aria-hidden />;
  }
  if (category?.includes("Cloud") || category?.includes("Infra")) {
    return <FiLayers className={`${className} text-blue-500`} aria-hidden />;
  }
  if (category?.includes("API") || category?.includes("Code") || category?.includes("DevOps")) {
    return <FiCode className={`${className} text-indigo-500`} aria-hidden />;
  }
  if (category?.includes("Incident") || category?.includes("Alert") || category?.includes("Observability")) {
    return <FiActivity className={`${className} text-emerald-500`} aria-hidden />;
  }
  if (category?.includes("Automation") || category?.includes("Orchestration")) {
    return <FiZap className={`${className} text-amber-500`} aria-hidden />;
  }

  return <FiBox className={`${className} text-zinc-500`} aria-hidden />;
}
